customCSS:
/* Gabarit Produit relief – carte produit avec relief 3D au survol (inspiration CodePen krautgti/VwXNRYE,
   "Nike Product Card Parallax 3D") – variables : --crsl-produit-relief-radius, --crsl-produit-relief-accent,
   --crsl-produit-relief-duration, --crsl-produit-relief-shadow.
   Le tilt suivant le pointeur (VanillaTilt dans l'original) demande du JS ; les gabarits inwink n'ont que du
   customCSS, donc le relief est un tilt fixe au survol/focus, pas un suivi du pointeur en temps réel.
   Titre et pré-titre sont utilisés comme les deux inscriptions géantes en filigrane (au lieu d'un nom de produit
   classique), révélées au survol. Couleur d'accent : palette cyclique par item, remplaçable globalement via
   --crsl-produit-relief-accent ou --crsl-accent (pas de champ couleur par item). */
##contentid .inwink-item { container-type: inline-size; }
##contentid .itemcontent {
  position: relative; display: block; aspect-ratio: 3 / 4; margin: 0; padding: 0;
  border-radius: var(--crsl-produit-relief-radius, var(--crsl-radius, 20px));
  overflow: visible; isolation: isolate;
  transform-style: preserve-3d; perspective: 1000px;
  transition: transform var(--crsl-produit-relief-duration, var(--crsl-duration, .5s)) cubic-bezier(.03,.98,.52,.99);
  background: radial-gradient(ellipse at right top, var(--pr-c, #9bdc28) 0%, #fff 47%, #fff 100%);
}
##contentid .itemcontent::before {
  content: ""; position: absolute; inset: 0; z-index: 0; border-radius: inherit; padding: .155rem;
  background: linear-gradient(45deg, transparent, transparent, var(--pr-c, #9bdc28)) border-box;
  -webkit-mask: linear-gradient(#fff 0 0) padding-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: destination-out; mask-composite: exclude; pointer-events: none;
}
##contentid .itemcontent:hover, ##contentid .itemcontent:focus-within {
  transform: perspective(1000px) rotateX(6deg) rotateY(-8deg) scale(1.04);
}
##contentid .inwink-item:nth-of-type(5n+1) .itemcontent { --pr-c: var(--crsl-produit-relief-accent, var(--crsl-accent, #9bdc28)); }
##contentid .inwink-item:nth-of-type(5n+2) .itemcontent { --pr-c: var(--crsl-produit-relief-accent, var(--crsl-accent, #1da3c3)); }
##contentid .inwink-item:nth-of-type(5n+3) .itemcontent { --pr-c: var(--crsl-produit-relief-accent, var(--crsl-accent, #eb0e2f)); }
##contentid .inwink-item:nth-of-type(5n+4) .itemcontent { --pr-c: var(--crsl-produit-relief-accent, var(--crsl-accent, #a855f7)); }
##contentid .inwink-item:nth-of-type(5n+5) .itemcontent { --pr-c: var(--crsl-produit-relief-accent, var(--crsl-accent, #f2b441)); }
##contentid .pr-circle {
  position: absolute; z-index: 1; top: 50%; left: 50%; width: 55%; max-width: 200px; aspect-ratio: 1;
  border-radius: 50%; background: var(--pr-c, #9bdc28);
  transform: translate3d(-50%, -50%, 0);
  transition: transform var(--crsl-produit-relief-duration, var(--crsl-duration, .5s));
}
##contentid .itemcontent:hover .pr-circle, ##contentid .itemcontent:focus-within .pr-circle {
  transform: translate3d(-50%, -50%, 35px);
}
##contentid .pr-picture { position: absolute; inset: 0; z-index: 2; pointer-events: none; }
##contentid .itemcontent.image-cutout .pr-product {
  position: absolute; top: 50%; left: 50%; max-width: 78%; max-height: 78%; width: auto; height: auto;
  object-fit: contain; transform: translate3d(-50%, -50%, 0) rotate(-15deg);
  transition: transform var(--crsl-produit-relief-duration, var(--crsl-duration, .5s));
  filter: drop-shadow(var(--crsl-produit-relief-shadow, var(--crsl-shadow, 0 20px 25px rgba(0,0,0,.35))));
}
##contentid .itemcontent.image-cutout:hover .pr-product, ##contentid .itemcontent.image-cutout:focus-within .pr-product {
  transform: translate3d(-50%, -50%, 90px) rotate(-15deg);
}
##contentid .itemcontent:not(.image-cutout) .pr-product {
  position: absolute; top: 50%; left: 50%; width: min(60cqi, 200px); height: min(60cqi, 200px); object-fit: cover; border-radius: 50%;
  border: 4px solid rgba(255,255,255,.7); transform: translate3d(-50%, -50%, 0);
  transition: transform var(--crsl-produit-relief-duration, var(--crsl-duration, .5s));
}
##contentid .itemcontent:not(.image-cutout):hover .pr-product, ##contentid .itemcontent:not(.image-cutout):focus-within .pr-product {
  transform: translate3d(-50%, -50%, 60px);
}
##contentid .pr-word {
  position: absolute; z-index: 3; margin: 0; line-height: .85; font-weight: 900; font-style: italic;
  color: #1a1d19; opacity: 0; pointer-events: none;
  transition: opacity var(--crsl-produit-relief-duration, var(--crsl-duration, .5s)), transform var(--crsl-produit-relief-duration, var(--crsl-duration, .5s));
}
##contentid .pr-word-lg { top: .8rem; left: 1rem; max-width: 58%; font-size: clamp(1.4rem, 13cqi, 2.6rem); transform: translateY(-8px); }
##contentid .pr-word-sm { top: .9rem; right: 1rem; max-width: 38%; font-size: clamp(.9rem, 8cqi, 1.5rem); text-align: right; transform: translateY(-8px); }
##contentid .itemcontent:hover .pr-word, ##contentid .itemcontent:focus-within .pr-word { opacity: .4; transform: none; }
##contentid .pr-buy {
  position: absolute; z-index: 4; left: 50%; bottom: 0; transform: translate3d(-50%, 0, 0);
  background: var(--pr-c, #333); color: #fff; text-decoration: none; font-weight: 600; white-space: nowrap;
  padding: .55rem 1.4rem; border-radius: 30px; opacity: 0;
  transition: opacity var(--crsl-produit-relief-duration, var(--crsl-duration, .5s)), bottom var(--crsl-produit-relief-duration, var(--crsl-duration, .5s));
}
##contentid .itemcontent:hover .pr-buy, ##contentid .itemcontent:focus-within .pr-buy { bottom: 1.4rem; opacity: 1; }
@media (prefers-reduced-motion: reduce) {
  ##contentid .itemcontent, ##contentid .pr-product, ##contentid .pr-circle, ##contentid .pr-word, ##contentid .pr-buy { transition: none; }
  ##contentid .itemcontent:hover, ##contentid .itemcontent:focus-within { transform: none; }
}
